#!/usr/bin/env python3
"""Run from project root: python3 fix_persist.py"""
import base64, os, sys
if not os.path.exists("app"):
    print("ERROR: run from project root (where app/ exists)"); sys.exit(1)
FILES = {
    "lib/vos/sessionStore.ts": "",
    "lib/vos/userAssetStore.ts": "",
    "lib/vos/commands.ts": "",
    "components/vos/VerificationTerminal.tsx": "",
    "components/onboarding/AssetOwnerOnboarding.tsx": "",
    "app/dashboard/page.tsx": "",
    "app/terminal/page.tsx": "",
}
for path, enc in FILES.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    open(path, "w", encoding="utf-8", newline="\n").write(content)
    print(f"WRITTEN  {path}  ({len(content.splitlines())} lines)")
print("""
PERSISTENCE LAYER + FOCUS FIX INSTALLED

What changed:
  1. lib/vos/sessionStore.ts          Anonymous session ID (localStorage)
  2. lib/vos/userAssetStore.ts        Append-only asset lifecycle store
  3. lib/vos/commands.ts              + my assets, track, submit, session commands
  4. components/vos/VerificationTerminal.tsx
                                      Memoized InputBar — focus survives re-renders
                                      16px input prevents iOS zoom-blur
                                      requestAnimationFrame refocus on submit
  5. components/onboarding/AssetOwnerOnboarding.tsx
                                      Now persists to userAssetStore on submit
                                      Shows confirmation + dashboard link
  6. app/dashboard/page.tsx           NEW route — wallet-style dashboard
                                      Session ID, asset list, lifecycle stepper,
                                      append-only timeline, simulate transitions
  7. app/terminal/page.tsx            + DASHBOARD nav link
                                      Terminal wrapper height-isolated

Demo flow for VCs:
  /terminal → submit an asset (4-step flow) → record persists
  /dashboard → see asset with DRAFT → SUBMITTED → IN_REVIEW → VERIFIED stepper
  /terminal → run \"my assets\" or \"track USR-XXXXXX\"
  Click SIMULATE NEXT STATE on dashboard to walk through lifecycle

Everything is localStorage — zero backend cost. Swappable to Supabase later.

Run:
  npm run build
  git add -A
  git commit -m \"feat: persistence layer — session, asset store, dashboard, focus-stable input\"
  git push origin main
""")
